insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('afe9db16-1b83-4292-ba6f-e10ecbe6ac93', 'ja', '惹かれ合いの場面での「社会的な立ち位置」とは、何ですか？', '["経済的な成功や、有名であること", "外見だけ", "一緒に来た友人の数", "周りが自分にどう反応するかにもとづく、見られ方としての価値"]'::jsonb, '立ち位置とは、その場が自分にどう反応するかのことで、周りから大切にされていると伝えます。')
