insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('49c55c64-36bd-4961-9847-6467136116c3', 'ja', 'イベントに誘われましたが、疲れを感じています。何を優先するべきですか？', '["毎回、心地よさのために家にいる", "関わる機会を増やすために、それでも行く", "エネルギーが万全になるのを待つ", "無理な付き合いを避けるために、断る"]'::jsonb, '疲れていても「はい」と言うことで、場数と、つながりの可能性が増えます。')
