insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('219c6ef8-a1ff-4dbe-8af3-fa8686d0e3c1', 'ja', '夜の店と比べたときの、身近な場所での練習の一番の利点は何ですか？', '["やり取りが、週末に限られること", "いつもの環境が、練習の場に変わること", "場数のひとつひとつに、特別な外出が必要になること", "より良い結果のために、プレッシャーを高く保てること"]'::jsonb, '日常の場所は、プレッシャーの少ない機会を、いくらでも与えてくれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('614a2ff0-a42d-4640-8fe2-752885cd8ed4', 'ja', '人が集まる場での「ホームグラウンドの強み」とは、何ですか？', '["なじみのある場所にいることから来る自信", "顔なじみの常連として認識されていることで得られる、社会的証明と立ち位置", "店の間取りや、そこにいる人を知っているという有利さ", "声をかけることをそれほど怖く感じさせない、居心地のよさ"]'::jsonb, 'ホームグラウンドの強みとは、顔なじみの常連であることから来る、社会的証明と立ち位置のことです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('91be9da9-35e2-4ee6-a859-ebc43437dadd', 'ja', '「顔なじみの常連」であることは、周りに何を伝えますか？', '["明らかに、この場所の一員だということ", "ほかの人たちが、すでに受け入れ、確かめた相手だということ", "ふつうの客より、お金や地位があるということ", "関わっても安全な相手だということ"]'::jsonb, 'この場の一員であること、周りに確かめられていること、安全であること。このサインが、ホームグラウンドの強みです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7755c8f9-1d23-4c93-b84c-9bb4a6f5047f', 'ja', 'ジムで、ホームグラウンドの強みを築く方法は、どれですか？', '["顔を覚えてもらえるよう、同じような時間帯に継続して通う", "スタッフや常連と、短く感じのいいやり取りを交わす", "恋愛的に関心のある人とだけ、関わる", "前に見かけたことのある顔に、あいさつする"]'::jsonb, '継続して通うこと、スタッフや常連との感じのいいやり取り、顔なじみへのあいさつ。それが、ホームグラウンドを築きます。')
