insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4a4122bd-a43e-4662-aef4-08635258b40c', 'ja', '場数を重ねることを最もよく支える考え方は、どれですか？', '["一回一回が、神経系に良いことを教えている", "声をかけたら、必ずどこかにつながらなければならない", "関わる機会より、結果のほうが大切だ", "できるときは、居心地の悪さを避ける"]'::jsonb, 'どんなやり取りも、結果に関係なく、練習として数に入ります。')
