insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('659f514c-7bf3-425d-9c1e-cf5df2bb69ef', 'ja', '声をかけても手応えがなく、何の結果も得られません。これをどう捉えるべきですか？', '["慣れに向けた、価値ある一回", "不安を強める失敗", "もっと良いセリフが必要だという証拠", "今日はやめる理由"]'::jsonb, 'どんなやり取りも、結果に関係なく、前向きな学びにつながります。')
