insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e225e86-4aa9-4111-b01c-711e3725c89f', 'ja', '意味のある場数を増やす行動は、どれですか？', '["一日にひとつの、小さなやり取り", "自信が持てるまで待つこと", "プレッシャーの少ない、継続した場数", "強く惹かれたときだけ、声をかけること"]'::jsonb, '激しさよりも、継続と頻度のほうが大切です。')
