insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e6b9ff5d-fc7a-4e92-91d3-57411235152b', 'ja', '練習を長く休んでいるあいだ、心理的に何が起こりますか？', '["スキルがさらに強まる", "避ける癖と不安が、根づく時間を得る", "神経回路が、効率的なままでいる", "進歩が、自動的に積み重なる"]'::jsonb, '休んでいるあいだに、心は、行動しない新しい理由をつくり出す余地を得ます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dd2cece1-3524-4319-bd95-d773079fa01b', 'ja', '無理なく続けられる継続を支える行動は、どれですか？', '["現実的な、週の最低ラインを決めること", "自信が持てるまで待つこと", "場数のあいだを、長く空けないこと", "小さなやり取りも、ちゃんとした一回として扱うこと"]'::jsonb, '激しさよりも、流れのほうが大切です。進歩は、一気にやることからではなく、続けることから生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3529af51-9b76-41c8-868a-2a04a415dc15', 'ja', '「スキルを練習している」から「それをする人間である」へと自己認識が変わるとき、何が起こりますか？', '["その行動が、自己イメージと切り離せなくなる", "自分はうまくやれているという、外からの承認が必要なくなる", "その行為が、「していること」から「自分という人間」へ移る", "埋めるべきすき間がないので、勇気がもう必要なくなる"]'::jsonb, '行動が自分という人間と切り離せなくなり、「していること」が「自分という人間」になり、勇気を必要とするすき間がなくなる。それが、自己認識の変化です。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('242a1957-a048-451a-9da7-8ab630640b24', 'ja', '自然にできる段階に達すると、なぜ声をかけるのに「勇気が必要なくなる」のですか？', '["何度もやってきたので、恐れが完全に消えるから", "自分という人間と、していることのあいだに、すき間がないから", "成功を重ねた自信が、ためらいをすべてなくすから", "腕が上がりすぎて、結果がもうどうでもよくなるから"]'::jsonb, '本来の自分に逆らって、無理に行動しているのではありません。ただ、自分という人間を表現しているのです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('371a7413-becb-4f2b-a50d-96a6e2786c70', 'ja', 'スキルを伸ばすうえでの「実験のマインドセット」を定義するものは、何ですか？', '["一回一回のやり取りを、本番の演技として扱うこと", "成功を、結果で測ること", "やり取りを、データ集めとして扱うこと", "断られるのを避けること"]'::jsonb, 'どのやり取りも役に立ちます。次に何を変えればいいかを教えてくれるからです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8a3d26a9-590a-4af0-95f0-d6c8c35f7896', 'ja', 'ユーモアを試して、2回続けて空振りに終わります。実験のマインドセットに従うと、どうするべきですか？', '["自分にユーモアは向いていない", "声をかけるのをやめる", "もっと良い冗談を暗記する", "別のタイプのユーモアや、別の場面で試す"]'::jsonb, 'どのやり取りも、たとえうまくいかなくても、次に何を変えればいいかを教えてくれます。')
