insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28e0261e-75cb-4bdc-917c-8d6e653f374a', 'ja', '実験のマインドセットは、断られる痛みをどうやって減らしますか？', '["すべての結果に、自尊心を結びつける", "やり取りを、データ集めとして扱う", "断られたことを、価値ある情報として見る"]'::jsonb, '結果は、自分の価値の証明ではなく、学びの機会になります。')
