insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b8b12ca4-eea8-4651-a0ba-a39ced8e6aef', 'ja', 'もともと物静かで、よく観察するタイプです。一番合う駆け引きのスタイルは、どれですか？', '["矢継ぎ早の冗談と掛け合い", "長い説明", "間と、落ち着いたアイコンタクト", "絶えず褒めること"]'::jsonb, '緊張感の生み方は、自分の気質に合っているべきです。')
