insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('30871b25-0072-4ec6-a580-9ac5cb667148', 'ja', '自分らしいスタイルは、なぜ借りもののテクニックを上回るのですか？', '["本物のつながりに使える、頭のリソースが空くから", "もともとの人柄の強みと一致しているから", "演技を保つために、ふりをする必要があるから"]'::jsonb, '自分らしくいることは、労力を減らし、すでにうまくいっているものを活かします。')
