insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3d6c847d-5687-4a4a-a269-96782bfa828d', 'ja', '声をかけても、礼儀正しい返事をもらって、すぐに終わることがよくあります。つまずきポイントは、どこですか？', '["関心をつかむ、うまい話しかけ方", "体の面で距離を縮めること", "長い会話を続けること", "うまく次につなげること"]'::jsonb, '結果が変わるのは、やり取りの中の一番弱い部分に練習を集中させたときです。')
