insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b31c3930-629e-4aab-974a-035d198918d4', 'ja', '自分の弱点を、どうやって正確に見つけますか？', '["全体的な自信の問題だと決めつける", "複数のやり取りで、繰り返し失敗する箇所を観察する", "いつも決まって崩れる場所のパターンを振り返る"]'::jsonb, 'つまずきポイントは、具体的な、繰り返し崩れる瞬間から見えてきます。')
