insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e977c9fd-3fd5-421d-b9c4-259a05b8af45', 'ja', '成長の停滞期を抜け出すのに役立つ方法は、どれですか？', '["意図的に難易度を上げること", "環境を変えること", "やる気を取り戻すために、長く休むこと", "具体的な小さなスキルひとつに集中すること"]'::jsonb, '新しい挑戦は、適応と進歩を促します。長い休みは、避ける癖を強めます。')
